private static List<Long> changedKeys(SortedMap<Long,String> before,SortedMap<Long,String> after){
    List<Long> changed=new ArrayList<>();Iterator<Map.Entry<Long,String>> left=before.entrySet().iterator(),right=after.entrySet().iterator();
    Map.Entry<Long,String> a=left.hasNext()?left.next():null,b=right.hasNext()?right.next():null;
    while(a!=null||b!=null){
        Long id;String old,value;
        if(b==null||(a!=null&&a.getKey()<b.getKey())){id=a.getKey();old=a.getValue();value="[]";a=left.hasNext()?left.next():null;}
        else if(a==null||b.getKey()<a.getKey()){id=b.getKey();old="[]";value=b.getValue();b=right.hasNext()?right.next():null;}
        else{id=a.getKey();old=a.getValue();value=b.getValue();a=left.hasNext()?left.next():null;b=right.hasNext()?right.next():null;}
        if(!old.equals(value))changed.add(id);
    }
    return changed;
}
